pub(crate) fn registry_help_seed_for_id(function_id: &str) -> Option<&'static RegistryHelpSeed> {
    REGISTRY_HELP_SEEDS
        .iter()
        .find(|seed| seed.function_id.eq_ignore_ascii_case(function_id))
}
